execFile("ps", ["-o", "pid=,lstart=", "-p", pids.join(",")], { timeout: PS_TIMEOUT_MS, env: { ...process.env, LC_ALL: "C", TZ: "UTC" } }, (_error, stdout) => {
            // `ps` exits 1 when one of the pids is gone; its output still holds
            // the live ones.
            for (const line of String(stdout ?? "").split("\n")) {
                const match = /^\s*(\d+)\s+(.+?)\s*$/.exec(line);
                if (match)
                    result.set(Number(match[1]), normalizeStart(match[2]));
            }
            resolve(result);
        })

